{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C19"],
      "claim": "Celiprolol, a close structural analogue sharing the tert-butylamino aryloxypropanolamine and urea motif, has a baseline oral bioavailability of 30–70% with negligible metabolism; its transporter-limited absorption makes it susceptible to rifampin-mediated P-gp induction, supporting that the query's F would fall below 20% under rifampin.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Pafenolol, another urea-containing beta-blocker, has a mean systemic availability of 27.5% after a 40 mg oral solution, demonstrating that this scaffold can sit near the 20% threshold; rifampin induction would be expected to lower the query below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Penbutolol has 90% oral bioavailability, but it lacks the urea/efflux-liability motif and is therefore less transferable to the query under rifampin co-treatment.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query (bucindolol) is a tert-butylamino aryloxypropanolamine urea beta-blocker with moderate baseline oral bioavailability and CYP3A4/P-gp liability. Rifampin is a strong inducer of these pathways and is expected to reduce F below the 20% threshold. The most relevant urea-containing analogues (celiprolol, pafenolol) have moderate or near-threshold F, while high-F analogues lack the urea/efflux liability.",
  "evidence_gaps": [
    "No direct bucindolol F measurement under rifampin is provided in the evidence set.",
    "The magnitude of rifampin-mediated reduction is inferred from known induction of CYP3A4/P-gp and analogue behavior rather than from a direct query measurement."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

